function buildIntegrativeEvidenceGuide(ctx,message=''){
  const c=clean(ctx)||{}, lumi=c.lumi||{};
  const precision=Array.isArray(lumi.completedPrecision)?lumi.completedPrecision:[];
  const precisionText=precision.flatMap(p=>(Array.isArray(p.answers)?p.answers:[]).map(a=>`${a?.question||''} ${a?.answer||''}`)).join(' ');
  const t=normText([
    message,
    lumi.area||'',
    ...(Array.isArray(lumi.concerns)?lumi.concerns:[]),
    c.selfConcern||'',
    precisionText
  ].join(' '));
  const scored=LUMI_INTEGRATIVE_EVIDENCE_GUIDES.map(g=>({
    g,
    score:g.keywords.reduce((s,k)=>s+(t.includes(normText(k))?1:0),0)
  })).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,2);
  if(!scored.length){
    return `[통합상담 근거수준 가이드]
- 먼저 현대의학적으로 확인 가능한 원인과 안전을 설명합니다.
- 자연치유는 수면·보습·세정·자외선·마찰·스트레스 같은 회복환경 관리 중심으로 설명합니다.
- 한의학은 전통적 해석으로 구분하고, 한약·침·뜸·보조제가 표준치료를 대신한다고 말하지 않습니다.
- 자연유래·천연도 알레르기와 자극 가능성이 있습니다.`;
  }
  return `[현재 고민과 관련된 통합상담 참고]
${scored.map(({g})=>`■ ${g.topic}
- 현대의학: ${g.medical}
- 한의학적 관점: ${g.traditional}
- 생활·자연관리: ${g.natural}
- 근거표시: ${g.evidence}`).join('\n\n')}
- 고객에게 A/B/C/D 글자를 매번 읽어줄 필요는 없습니다. 필요할 때 “근거가 비교적 분명합니다 / 보조적으로 볼 수 있습니다 / 전통적 사용이지만 근거는 제한적입니다”처럼 쉬운 말로 설명합니다.`;
}


