function findVerifiedProduct(name){
  return MAIIM_VERIFIED_PRODUCTS.find(p=>p.name===name)||null;
}
function productSafetyPenalty(p,signals){
  if(!p)return 999;
  const ing=String(p.ingredients||'');
  let penalty=0;
  if(signals.sensitive){
    if(ing.includes('메칠이소치아졸리논')) penalty+=55;
    if(ing.includes('변성알코올')) penalty+=18;
    if(ing.includes('향료')) penalty+=8;
  }
  if(signals.inflamed && /마사지|바디솔트|뷰티 칼라/.test(p.name)) penalty+=80;
  if(signals.scalpInflamed && /뷰티 칼라/.test(p.name)) penalty+=100;
  return penalty;
}
function collectProductSignals(ctx,message=''){
  const c=clean(ctx)||{}, lumi=c.lumi||{};
  const scores=lumi?.basicAnalysis?.scores&&typeof lumi.basicAnalysis.scores==='object'?lumi.basicAnalysis.scores:{};
  const precision=Array.isArray(lumi.completedPrecision)?lumi.completedPrecision:[];
  const precisionText=precision.flatMap(p=>(Array.isArray(p.answers)?p.answers:[]).map(a=>`${a?.question||''} ${a?.answer||''}`)).join(' ');
  const risks=precision.flatMap(p=>[
    ...(Array.isArray(p.urgentRisks)?p.urgentRisks:[]),
    ...(Array.isArray(p.risks)?p.risks:[])
  ]).join(' ');
  const t=normText([
    message,
    lumi.area||'',
    ...(Array.isArray(lumi.concerns)?lumi.concerns:[]),
    c.selfConcern||'',
    precisionText
  ].join(' '));
  const gender=String(lumi.gender||c.gender||'');
  const sig={
    t,scores,urgent:Boolean(precision.some(p=>Array.isArray(p.urgentRisks)&&p.urgentRisks.length)),
    sensitive:Number(scores.sensitive||0)>=50 || /민감|홍조|따가|화끈|자극/.test(t),
    inflamed:/진물|고름|심한 통증|열감|빠르게 번|출혈/.test(t+' '+risks),
    scalpInflamed:/두피/.test(t) && /진물|고름|통증|상처|딱지/.test(t+' '+risks)
  };
  sig.dry=Number(scores.barrier||0)>=50 || /건조|당김|장벽|푸석|보습/.test(t);
  sig.scalp=Number(scores.scalp||0)>=50 || /두피|비듬|각질|머리 가려|피지/.test(t);
  sig.hairDamage=/모발 손상|손상 모발|푸석한 모발|염색모|펌.*손상|트리트먼트/.test(t);
  sig.aging=Number(scores.aging||0)>=50 || /주름|탄력|노화|처짐/.test(t);
  sig.pigment=Number(scores.pigment||0)>=50 || /기미|주근깨|잡티|검버섯|색소|피부톤|칙칙/.test(t);
  sig.eye=/눈가|다크서클|눈 밑|아이크림/.test(t);
  sig.bodyDry=Number(scores.bodyitch||0)>=50 || /몸 피부.*건조|전신.*건조|바디.*건조|몸.*가려/.test(t);
  sig.hand=/손.*건조|손.*거칠|핸드/.test(t);
  sig.sun=/자외선|선크림|선 에센스|햇빛/.test(t);
  sig.cleansing=/클렌징|세안|메이크업.*지우|노폐물/.test(t);
  sig.men=/남성|남자|면도/.test(t)||/남성/.test(gender);
  return sig;
}
function productPriorityCandidates(ctx,message=''){
  const s=collectProductSignals(ctx,message);
  if(s.urgent) return {signals:s,items:[],reason:'현재 기록에 즉시 확인이 필요한 신호가 있어 제품 추천보다 안전 확인을 우선합니다.'};
  const buckets=[];
  const add=(key,boost=0)=>{
    for(const row of (MAIIM_RECOMMENDATION_RULES[key]||[])){
      const [name,base,why]=row, p=findVerifiedProduct(name);
      if(p)buckets.push({p,score:base+boost-productSafetyPenalty(p,s),why,key});
    }
  };
  if(s.dry)add('dry',Number(s.scores.barrier||0)/10);
  if(s.sensitive)add('sensitive',Number(s.scores.sensitive||0)/10);
  if(s.scalp)add('scalp',Number(s.scores.scalp||0)/10);
  if(s.hairDamage)add('hairDamage',12);
  if(s.aging)add('aging',Number(s.scores.aging||0)/10);
  if(s.pigment)add('pigment',Number(s.scores.pigment||0)/10);
  if(s.eye)add('eye',10);
  if(s.bodyDry)add('bodyDry',Number(s.scores.bodyitch||0)/10);
  if(s.hand)add('hand',10);
  if(s.sun)add('sun',10);
  if(s.cleansing)add('cleansing',10);
  if(s.men)add('men',6);

  const exact=MAIIM_VERIFIED_PRODUCTS.filter(p=>{
    const n=normText(p.name); return n && s.t.includes(n);
  }).map(p=>({p,score:220-productSafetyPenalty(p,s),why:'고객이 직접 언급한 제품이므로 현재 상태와의 적합성을 먼저 확인합니다.',key:'exact'}));
  buckets.push(...exact);

  const merged=new Map();
  for(const x of buckets){
    const prev=merged.get(x.p.name);
    if(!prev||x.score>prev.score)merged.set(x.p.name,x);
  }
  const items=[...merged.values()].filter(x=>x.score>35).sort((a,b)=>b.score-a.score);
  return {signals:s,items,reason:''};
}
function buildProductRecommendationGuide(ctx,message=''){
  const r=productPriorityCandidates(ctx,message), s=r.signals;
  if(r.reason)return `[제품 추천 우선순위]\n- ${r.reason}\n- 제품 판매 연결은 위험신호 확인 뒤로 미룹니다.`;
  if(!r.items.length)return `[제품 추천 우선순위]\n- 현재 정보만으로는 제품 1순위를 억지로 만들지 않습니다. 고객이 가장 불편한 피부·두피 고민을 먼저 확인합니다.`;
  const top=r.items.slice(0,2);
  const lines=top.map((x,i)=>`${i+1}순위: ${x.p.name} — ${x.why}${productSafetyPenalty(x.p,s)>0?' 단, 현재 민감도에 따라 자극 가능 성분 반응을 확인합니다.':''}`);
  return `[제품 추천 우선순위 — 내부 상담 가이드]
${lines.join('\n')}
- 위 숫자 순위는 고객에게 기계적 점수로 말하지 않습니다. “현재 고민에는 1순위로 ○○를 보겠습니다”처럼 자연스럽게 설명합니다.
- 고객이 지금 다른 고민을 새로 말하면 위 순위를 고집하지 말고 그 질문을 기준으로 다시 판단합니다.
- 1순위가 적합하면 이유 2~3가지와 사용법을 설명한 뒤 구매상담 연결을 한 번 제안합니다.
- 염증·진물·고름·심한 통증 등 위험신호가 생기면 제품판매보다 진료/안전 안내를 우선합니다.`;
}

function selectProducts(message,ctx,limit=7){
  const t=normText(message+' '+JSON.stringify(ctx?.lumi?.concerns||[])+' '+(ctx?.lumi?.area||''));
  const priority=productPriorityCandidates(ctx,message).items||[];
  const scored=MAIIM_VERIFIED_PRODUCTS.map(p=>{
    let score=0; const n=normText(p.name);
    if(n && t.includes(n)) score+=60;
    for(const token of n.split(/\s+/)){ if(token.length>=2 && t.includes(token)) score+=2; }
    if(p.area?.some(a=> (a==='face'&&/얼굴|피부|주름|색소|여드름|홍조|보습/.test(t)) || (a==='scalp'&&/두피|비듬|탈모/.test(t)) || (a==='hair'&&/모발|헤어|샴푸|트리트먼트/.test(t)) || (a==='body'&&/전신|몸|바디|손|발|가려움/.test(t)))) score+=4;
    if(/성분|전성분|ingredient/.test(t)) score+=1;
    return {p,score};
  }).sort((a,b)=>b.score-a.score);
  const out=[],seen=new Set();
  for(const x of [...priority,...scored.filter(x=>x.score>0)]){
    const p=x.p;if(!p||seen.has(p.name))continue;seen.add(p.name);out.push(p);
    if(out.length>=limit)return out;
  }
  if(out.length)return out;
  const area=normText(ctx?.lumi?.area||'');
  const fallback=/두피|모발/.test(area)
    ?MAIIM_VERIFIED_PRODUCTS.filter(p=>p.area?.includes('scalp')||p.area?.includes('hair'))
    :(/전신|몸|손|발/.test(area)
      ?MAIIM_VERIFIED_PRODUCTS.filter(p=>p.area?.includes('body'))
      :MAIIM_VERIFIED_PRODUCTS.filter(p=>p.area?.includes('face')));
  return fallback.slice(0,limit);
}
function selectIngredients(message,limit=8){
  const t=normText(message);
  const hits=LUMI_INGREDIENT_KNOWLEDGE.filter(x=>(x.aliases||[]).some(a=>t.includes(normText(a))));
  if(hits.length) return hits.slice(0,limit);
  if(/성분|화장품|보습|장벽|민감|여드름|두피|탈모|바디/.test(t)) return LUMI_INGREDIENT_KNOWLEDGE.slice(0,limit);
  return [];
}
function selectDermGuides(message,ctx,limit=4){
  const t=normText(message+' '+(ctx?.lumi?.area||'')+' '+JSON.stringify(ctx?.lumi?.concerns||[]));
  const scored=LUMI_DERM_GUIDES.map(g=>({g,score:(g.keywords||[]).reduce((n,k)=>n+(t.includes(normText(k))?1:0),0)})).sort((a,b)=>b.score-a.score);
  const hits=scored.filter(x=>x.score>0).slice(0,limit).map(x=>x.g);
  return hits.length?hits:LUMI_DERM_GUIDES.slice(0,2);
}
function productText(p,full=false){
  if(!p)return'';
  const main=`${p.name} [공식 상세 검증] — ${p.role}`;
  if(!full)return main;
  return `${main}\n전성분: ${p.ingredients}\n공식페이지: ${p.url}`;
}
function knowledgeForTurn(ctx,message,{realtime=false}={}){
  if(realtime) return realtimeKnowledgeForSession(ctx);
  const derm=selectDermGuides(message,ctx,4).map(x=>`- ${x.topic}: ${x.guide}`).join('\n');
  const ingredients=selectIngredients(message,realtime?14:8).map(x=>`- ${x.name}: ${x.use} 주의: ${x.caution}`).join('\n');
  const products=selectProducts(message,ctx,7);
  const prod=products.map(p=>productText(p,false)).join('\n\n');
  const priorityGuide=buildProductRecommendationGuide(ctx,message);
  const integrativeGuide=buildIntegrativeEvidenceGuide(ctx,message);
  const activeGuide=buildActiveConsultationGuide(ctx,message);
  return `[관련 피부 전문지식]\n${derm||'- 필요 정보에 맞춰 추가 질문'}\n\n${integrativeGuide}\n\n${activeGuide}\n\n${LUMI_SYSTEMIC_SKIN_KNOWLEDGE}\n\n[관련 성분 지식]\n${ingredients||'- 질문에 특정 성분이 있으면 기능과 주의를 구분해 설명'}\n\n${priorityGuide}\n\n[MAIIM 공식 제품 지식]\n${prod||'- 공식 상세 검증 제품을 찾지 못함'}\n\n[MAIIM 현재 전체 제품명 인덱스]\n${compactProductIndex()}\n\n[대표 타사 제품 비교 참고]\n${competitorReferenceText()}`;
}


// === LUMI v70 · 대화 타이밍 + MAIIM 브랜드/제품 인식 강화 ===
const MAIIM_BRAND_ALIASES = ['MAIIM','마임','마이임','마이메','마인'];
const MAIIM_QUICK_RECOMMENDATION_MAP = `
- 얼굴 건조·장벽: 1순위 라헬 나이트케어 보습젤(세라마이드NP·판테놀·히알루론산·우레아), 낮에는 라헬 데이케어 수분젤, 보습막·영양 보완은 라헬 모이스트 코팅 크림 또는 비에타 에센스 크림.
- 얼굴 민감·진정/전신 건조: 라헬 메디알로 젤 또는 라헬 데이케어 수분젤을 상태에 맞춰 우선 검토. 알코올·향료 등 자극 가능 성분은 민감도에 따라 함께 확인.
- 탄력·노화: 비에타 안티에이징 에센스, 비타 콜라겐 인텐시브 앰플, 비에타 에센스 크림을 고민과 제형 선호에 따라 검토.
- 눈가 주름·탄력: 비에타 에센스 아이 리페어 크림 또는 라헬 모이스트 오플루 아이크림. 다크서클 원인이 색소·혈관·꺼짐인지에 따라 화장품 기대 범위를 구분.
- 피부톤·결 정돈: 라헬 모이스트 부스팅 스킨. 민감하면 자극 반응을 먼저 확인.
- 밤 피부톤·탄력 집중관리: 비에타 화이트케어 나이트 세럼. 기능성 화장품 범위 안에서 피부톤·주름관리 보조로 설명하고, 민감 피부는 변성알코올·향료 반응을 확인.
- 가벼운 보습 루틴: 프레쉬가든 스킨 → 프레쉬가든 로션 젤. 산뜻한 제형을 선호하는 고객에게 고려하되, 두 제품 모두 알코올·향료가 있어 민감도 확인.
- 가벼운 세안: 프레쉬가든 클렌징 폼. 세안 후 당김이 반복되면 사용 빈도·양·물 온도를 먼저 조정.
- 메이크업·커버: 프레쉬가든 BB크림 W SPF31 PA++ 또는 비에타 스페셜 쿠션 파운데이션 SPF50+ PA+++. 피부질환 치료제품처럼 설명하지 않고 커버·메이크업·자외선차단 기능 중심으로 안내.
- 프리미엄 보습·탄력 루틴: 오클래식 골든 타임 스킨 → 아이크림/에센스 → 로션 → 크림 순으로 피부 상태와 필요한 단계만 선택. 모든 단계를 꼭 써야 한다고 강요하지 않음.
- 낮 피부톤·탄력 집중관리: 비에타 화이트케어 데이 세럼 + 자외선차단제. 색소질환 치료로 설명하지 않음.
- 보습·윤기 에센스: 라헬 모이스트 에센스 인 오일. 건조·윤기 고민에는 후보가 될 수 있으나 민감·보존제 알레르기 이력은 먼저 확인.
- 워시오프 진정 보조: 라헬 알로에 내추럴팩. 붉음·자극이 심한 피부질환 상태에서는 먼저 원인 확인.
- 시트마스크 보조관리: 라헬 곡물 마스크·한방 마스크. 고객 피부가 민감하면 향료/방부제 반응을 먼저 고려.
- 야간 집중 보습·탄력: 비타 콜라겐 슬리핑 팩. 기본 보습 루틴을 대체하는 필수품처럼 강요하지 않고 주 2~3회 보조관리 후보로 안내.
- 수시 보습: 비에타 에센스 미스트. 건조감이 있을 때 보조적으로 사용하며, 심한 장벽손상은 미스트만으로 해결된다고 말하지 않음.
- 메이크업 1차 세정: 라헬 내추럴 에센스 클렌징 오일. 사용 후 필요하면 피부 상태에 맞는 2차 세안을 검토.
- 피부 마사지: 라헬 알로에 뉴트리브 마사지크림. 민감·홍조·염증 상태에서는 마사지보다 자극 회피를 우선.
- 염색: 비에타 프리미엄 뷰티 칼라는 모발 색상 변경용 염모제로만 안내하고 피부·두피 증상 치료용으로 추천하지 않음.
- 여성 외부 민감 피부: 비에타 스페셜 이너케어 에센스는 외부 피부 보습·진정용 후보이며, 통증·분비물·출혈·감염 의심은 진료 우선.
- 오일 클렌징: 자온 생기 클렌징 오일. 메이크업·피지·노폐물 제거 목적이며 한방 원료를 포함하지만 피부질환 치료나 체질 교정으로 과장하지 않음.
- 향수: 조이인 오드 뚜왈렛. 향 제품으로만 안내하고 피부·두피 치료나 보습 제품으로 추천하지 않음.
- 얼굴 자외선: 비에타 페이스 선 에센스 SPF35 PA++. 야외활동 시간·도포량·재도포가 중요하며 자외선차단제는 제품만큼 사용법이 중요.
- 남성 피부: 세안 후 정돈은 비에타 포맨 클리어런스 토너, 보습은 비에타 포맨 리차징 에멀젼, 탄력·보습 집중은 비에타 포맨 콜라겐 에센스 젤을 피부 상태에 맞춰 검토.
- 두피 비듬·피지·각질: 라헬 헤어시스 샴푸 또는 비에타 헤어케어 에센스 샴푸. 두피 민감도와 사용 빈도를 함께 확인.
- 손상 모발·건조 모발: 라헬 헤어시스 트리트먼트, 비에타 헤어케어 에센스 트리트먼트/팩, 라헬 헤어시스 헤어 에센스를 모발 상태에 맞춰 제안.
- 전신 건조·보습: 비에타 바디케어 바디 에센셜 크림 또는 라헬 메디알로 젤. 매우 건조하면 크림, 가벼운 보습·진정은 젤을 우선 검토.
- 손 건조·거칠음: 라헬 내추럴 핸드 에센스 크림. 갈라짐·피부염이 심하면 자극요인 회피와 의료 확인도 함께 안내.
- 바디 세정: 비에타 바디케어 에센셜 바디 클렌저. 건조·민감하면 세정 시간과 물 온도도 함께 조정.
- 바디 각질: 비에타 바디케어 바디솔트. 갈라짐·진물·염증·심한 민감 상태에서는 마찰 사용을 피하거나 미룬다.
- 바디 자외선: 비에타 바디 선 에센스 SPF50+ PA+++.
`;

